    .replace(/&#39;/g, "'")
    .replace(/https?:\/\/[^\s]+/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/[\x00-\x09\x0B\x0C\x0E-\x1F\x7F]/g, '')
