    } else if (typeof item.json.body === 'string') {
      emailBodyText = item.json.body;
    } else if (item.json.bodyPreview) {
      emailBodyText = item.json.bodyPreview;
    } else if (item.json.textPlain) {
      emailBodyText = item.json.textPlain;
    }

    const cleanText = sanitizeText(emailBodyText);

    // Binary keys ophalen
    const hasBinary = !!item.binary;
    const binaryKeys = hasBinary ? Object.keys(item.binary) : [];

    // Inline afbeeldingen filteren (cid: attachments zijn signatures/logo's)
    // Alleen ECHTE bijlagen meenemen: PDF, Word, Excel, CSV, TXT
    const SKIP_MIMES = ['image/'];
    const SKIP_EXTS  = ['.jpg','.jpeg','.png','.gif','.webp','.svg','.bmp','.tiff'];
    const DOC_MIMES  = ['pdf','word','excel','spreadsheet','text/plain','text/csv',
                        'officedocument','opendocument'];
    const DOC_EXTS   = ['.pdf','.doc','.docx','.xls','.xlsx','.csv','.txt'];

    const docKeys = binaryKeys.filter(key => {
      const b = item.binary[key];
      if (!b) return false;
      const mime = (b.mimeType || '').toLowerCase();
      const name = (b.fileName || '').toLowerCase();

      // Afbeeldingen altijd skippen
      if (SKIP_MIMES.some(m => mime.startsWith(m))) return false;
      if (SKIP_EXTS.some(e => name.endsWith(e))) return false;

      // Alleen echte documenten meenemen
      return DOC_MIMES.some(m => mime.includes(m)) ||
             DOC_EXTS.some(e => name.endsWith(e));
    });

    const hasDocAttachment = docKeys.length > 0;

    const output = {
      json: {
        text: cleanText,
        attachmentExists: hasDocAttachment,  // TRUE alleen voor echte docs
        hasPDF: docKeys.some(k => {
          const b = item.binary?.[k];
          return (b?.mimeType || '').includes('pdf') ||
                 (b?.fileName || '').toLowerCase().endsWith('.pdf');
        }),
        docCount: docKeys.length,
