        bccRecipients: (item.json.bccRecipients || [])
          .map(r => r.emailAddress?.address || r).filter(Boolean),
        toRecipients: (item.json.toRecipients || [])
          .map(r => r.emailAddress?.address || r).filter(Boolean),
        subject: item.json.subject || 'No subject',
        date: item.json.receivedDateTime || item.json.createdDateTime || new Date().toISOString(),
        attachmentCount: docKeys.length,
        hasAttachmentsFlag: item.json.hasAttachments || false
      }
    };

    // Bijlage details toevoegen
    if (docKeys.length > 0) {
      output.json.attachments = docKeys.map(key => {
        const b = item.binary[key];
        return {
          binaryKey: key,
          filename: b.fileName || key,
          mimeType: b.mimeType || 'application/octet-stream',
          isPDF: (b.mimeType || '').includes('pdf') ||
                 (b.fileName || '').toLowerCase().endsWith('.pdf')
        };
      });
      output.binary = item.binary;  // Binary data doorgeven
    }

    results.push(output);

  } catch (error) {
    results.push({
      json: {
        text: item.json.bodyPreview || "Error extracting email body",
        error: error.message,
        emailId: item.json?.id || 'unknown',
        from: item.json?.from?.emailAddress?.address || 'unknown',
        subject: item.json?.subject || 'Unknown',
        attachmentExists: false,
        hasPDF: false,
        binaryKeys: []
      }
    });
  }
}

return results;

