  return [{
    json: {
      ...item.json,
      activePdfKey: null,
      noDocAttachment: true
    }
  }];
}

// Per document een apart item aanmaken
return docKeys.map(key => {
  const b = item.binary?.[key];
  const fileName = (b?.fileName || key).toLowerCase();
  const ext = fileName.split('.').pop();

  // Bepaal het juiste extract-type voor de Extract from File node
  let extractType = 'text';
  if (ext === 'pdf') extractType = 'pdf';
  else if (ext === 'csv') extractType = 'csv';
  else if (ext === 'xlsx' || ext === 'xls') extractType = 'xlsx';
  else if (ext === 'docx' || ext === 'doc') extractType = 'docx';

  return {
    json: {
