const config = $('Aggregate Config').first().json._config;
const loadingRates = config.loadingRates || [];

console.log('📋 Using ' + loadingRates.length + ' loading rates from Supabase');

const results = allItems.map(item => {
  const cargoQty = item.json.cargo_quantity || 0;
  const operation = (item.json.operation_type || '').toLowerCase();
  const portCode = item.json.port_code || '';
  const cargoType = (item.json.cargo_type || '').toLowerCase();

  let portStay = null;
  let loadingRate = null;

  if ((operation.includes('load') || operation.includes('discharge')) && cargoQty > 0) {
    const matchingRate = loadingRates.find(lr => {
      const lrCargo = (lr.cargo_type || '').toLowerCase();
      return cargoType.includes(lrCargo) || lrCargo.includes(cargoType);
    });

    if (matchingRate) {
      loadingRate = operation.includes('discharge')
        ? (matchingRate.discharge_rate || matchingRate.loading_rate)
        : matchingRate.loading_rate;

      portStay = cargoQty / loadingRate;

      if (matchingRate.heating_required && matchingRate.heating_buffer_percent > 0) {
        portStay = portStay * (1 + matchingRate.heating_buffer_percent / 100);
      }
      if (matchingRate.port_stay_buffer_percent > 0) {
        portStay = portStay * (1 + matchingRate.port_stay_buffer_percent / 100);
      }
    } else {
      loadingRate = 1000;
      portStay = cargoQty / loadingRate;
    }

    if (portCode.includes('OFFSHORE')) portStay = portStay * 1.2;
    portStay = Math.round(portStay * 2) / 2;
  }
  else if (operation.includes('bunker') && cargoQty > 0) {
    const rate = portCode.includes('OFFSHORE') || portCode.includes('OUTER_BAYS') ? 150 : 250;
    portStay = Math.round(((cargoQty / rate) + 2) / 24 * 1.2 * 2) / 2;
  }
  else if (operation.includes('sts') || operation.includes('ship-to-ship')) {
    portStay = cargoQty > 0 ? Math.ceil(((cargoQty / 1200) + 0.5) * 1.3 * 2) / 2 : 1;
  }
  else if (operation.includes('crew') || operation.includes('provision')) {
    portStay = 0.5;
  }
  else { portStay = 1; }

  if (portStay && portStay < 0.5) portStay = 0.5;

  return { ...item.json, port_stay: portStay, loading_rate: loadingRate };
});

return results.map(r => ({ json: r }));

